package cn.zhuatech.finops.deep;import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="fo_cloud_accounts",uniqueConstraints=@UniqueConstraint(columnNames={"organizationCode","accountCode"})) class CloudAccount{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Column(nullable=false,length=40)String organizationCode;@Column(nullable=false,length=50)String accountCode;@Column(nullable=false,length=30)String provider;@Column(nullable=false,length=120)String name;@Column(nullable=false,length=20)String status="DRAFT";LocalDateTime createdAt;protected CloudAccount(){}CloudAccount(String o,String c,String p,String n){organizationCode=o;accountCode=c;provider=p;name=n;createdAt=LocalDateTime.now();}}
@Entity @Table(name="fo_budgets",uniqueConstraints=@UniqueConstraint(columnNames={"organizationCode","costCenter","fiscalMonth"})) class CloudBudget{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Column(nullable=false,length=40)String organizationCode;@Column(nullable=false,length=50)String costCenter;@Column(nullable=false,length=7)String fiscalMonth;double budgetAmount;int warningPercent;@Column(nullable=false,length=20)String status="ACTIVE";protected CloudBudget(){}CloudBudget(String o,String c,String m,double b,int w){organizationCode=o;costCenter=c;fiscalMonth=m;budgetAmount=b;warningPercent=w;}}
@Entity @Table(name="fo_cost_records",uniqueConstraints=@UniqueConstraint(columnNames="providerLineId")) class CloudCostRecord{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Column(nullable=false,length=80)String providerLineId;@Column(nullable=false)Long accountId;@Column(nullable=false,length=50)String serviceCode;@Column(nullable=false,length=50)String resourceId;@Column(nullable=false,length=50)String costCenter;double amount;double baselineAmount;boolean tagged;LocalDate usageDate;LocalDateTime ingestedAt;protected CloudCostRecord(){}CloudCostRecord(String l,Long a,String s,String r,String c,double amount,double base,boolean t,LocalDate d){providerLineId=l;accountId=a;serviceCode=s;resourceId=r;costCenter=c;this.amount=amount;baselineAmount=base;tagged=t;usageDate=d;ingestedAt=LocalDateTime.now();}}
@Entity @Table(name="fo_cost_alerts",uniqueConstraints=@UniqueConstraint(columnNames="alertNo")) class CostAlert{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Column(nullable=false,length=100)String alertNo;@Column(nullable=false,length=40)String organizationCode;@Column(nullable=false,length=30)String alertType;@Column(nullable=false,length=20)String severity;@Column(nullable=false,length=300)String description;@Column(nullable=false,length=20)String status="OPEN";LocalDateTime createdAt;protected CostAlert(){}CostAlert(String n,String o,String t,String s,String d){alertNo=n;organizationCode=o;alertType=t;severity=s;description=d;createdAt=LocalDateTime.now();}}
@Entity @Table(name="fo_recommendations",uniqueConstraints=@UniqueConstraint(columnNames="recommendationNo")) class OptimizationRecommendation{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Version long version;@Column(nullable=false,length=50)String recommendationNo;@Column(nullable=false)Long accountId;@Column(nullable=false,length=50)String resourceId;@Column(nullable=false,length=40)String actionType;double estimatedMonthlySavings;double actualMonthlySavings;@Column(nullable=false,length=20)String status="PROPOSED";@Column(length=300)String executionNote;protected OptimizationRecommendation(){}OptimizationRecommendation(String n,Long a,String r,String t,double s){recommendationNo=n;accountId=a;resourceId=r;actionType=t;estimatedMonthlySavings=s;}}
